`timescale 1ns/1ps

module m_vlsi_apb4_csr #(
  // Parameter Description: select same-clock or asynchronous bus-to-register crossing logic.
  // Parameter values: 0 (synchronous) or 1 (asynchronous); default follows the workbook.
  // Parameter unit: none
  parameter logic [31:0] PARA_ASYNCHRONOUS = 32'd0,
  // Parameter Description: number of generated monitor registers.
  // Parameter values: 1 through 4; default follows the workbook.
  // Parameter unit: register count
  parameter logic [31:0] PARA_MONITOR_COUNT = 32'd2,
  localparam logic [31:0] LPARA_ADDR_W = 32'd16,
  localparam logic [31:0] LPARA_DATA_W = 32'd32,
  localparam logic [31:0] LPARA_STRB_W = 32'd4,
  localparam logic [31:0] LPARA_SYNC_STAGES = 32'd2,
  localparam logic [31:0] LPARA_ENGINE_OFFSET = 32'h0000,
  localparam logic [31:0] LPARA_PORT_0_OFFSET = 32'h0100,
  localparam logic [31:0] LPARA_PORT_1_OFFSET = 32'h0104,
  localparam logic [31:0] LPARA_PORT_2_OFFSET = 32'h0108,
  localparam logic [31:0] LPARA_MONITOR_BASE_OFFSET = 32'h0200,
  localparam logic [31:0] LPARA_MONITOR_OFFSET_STRIDE = 32'd4,
  localparam logic [31:0] LPARA_MONITOR_MAX_COUNT = 32'd4,
  localparam logic [31:0] LPARA_KEY_OFFSET = 32'h0400
) (
  // APB clock and reset
  input  wire                                 i_clk_apb,
  input  wire                                 i_rst_n_apb,

  // Register clock and reset (used only in asynchronous mode)
  input  wire                                 i_clk_reg,
  input  wire                                 i_rst_n_reg,

  // APB slave interface
  input  wire                                 i_apb_psel,
  input  wire                                 i_apb_penable,
  input  wire                                 i_apb_pwrite,
  input  wire  [LPARA_ADDR_W-1:0]             i_apb_paddr,
  input  wire  [LPARA_DATA_W-1:0]             i_apb_pwdata,
  input  wire  [LPARA_STRB_W-1:0]             i_apb_pstrb,
  input  wire  [2:0]                          i_apb_pprot,
  output logic                                o_apb_pready,
  output logic                                o_apb_pslverr,
  output logic [LPARA_DATA_W-1:0]             o_apb_prdata,

  // Access check control
  input  wire                                 i_protect_en,
  input  wire                                 i_slverr_en,

  // Register transaction event sideband
  output logic                                o_reg_rd_en,
  output logic [LPARA_ADDR_W-1:0]             o_reg_rd_addr,
  output logic                                o_reg_wr_en,
  output logic [LPARA_ADDR_W-1:0]             o_reg_wr_addr,

  // Register engine
  input  wire  [7:0]                          i_engine_events,
  output logic [3:0]                          o_engine_mode,
  output logic                                o_engine_start,
  input  wire                                 i_hw_wdata_engine_start,
  input  wire                                 i_hw_we_engine_start,
  output logic                                o_engine_fault,
  input  wire                                 i_hw_wdata_engine_fault,
  input  wire                                 i_hw_we_engine_fault,
  output logic                                o_engine_pending,
  input  wire                                 i_hw_wdata_engine_pending,
  input  wire                                 i_hw_we_engine_pending,
  output logic                                o_engine_overflow,
  input  wire                                 i_hw_wdata_engine_overflow,
  input  wire                                 i_hw_we_engine_overflow,
  output logic                                o_engine_done,
  input  wire                                 i_hw_wdata_engine_done,
  input  wire                                 i_hw_we_engine_done,

  // Register port_0
  input  wire  [7:0]                          i_port_0_event_count,
  output logic [3:0]                          o_port_0_mode,
  output logic                                o_port_0_start,
  input  wire                                 i_hw_wdata_port_0_start,
  input  wire                                 i_hw_we_port_0_start,
  output logic                                o_port_0_fault,
  input  wire                                 i_hw_wdata_port_0_fault,
  input  wire                                 i_hw_we_port_0_fault,
  output logic                                o_port_0_pending,
  input  wire                                 i_hw_wdata_port_0_pending,
  input  wire                                 i_hw_we_port_0_pending,
  output logic                                o_port_0_overflow,
  input  wire                                 i_hw_wdata_port_0_overflow,
  input  wire                                 i_hw_we_port_0_overflow,
  output logic                                o_port_0_done,
  input  wire                                 i_hw_wdata_port_0_done,
  input  wire                                 i_hw_we_port_0_done,

  // Register port_1
  input  wire  [7:0]                          i_port_1_event_count,
  output logic [3:0]                          o_port_1_mode,
  output logic                                o_port_1_start,
  input  wire                                 i_hw_wdata_port_1_start,
  input  wire                                 i_hw_we_port_1_start,
  output logic                                o_port_1_fault,
  input  wire                                 i_hw_wdata_port_1_fault,
  input  wire                                 i_hw_we_port_1_fault,
  output logic                                o_port_1_pending,
  input  wire                                 i_hw_wdata_port_1_pending,
  input  wire                                 i_hw_we_port_1_pending,
  output logic                                o_port_1_overflow,
  input  wire                                 i_hw_wdata_port_1_overflow,
  input  wire                                 i_hw_we_port_1_overflow,
  output logic                                o_port_1_done,
  input  wire                                 i_hw_wdata_port_1_done,
  input  wire                                 i_hw_we_port_1_done,

  // Register port_2
  input  wire  [7:0]                          i_port_2_event_count,
  output logic [3:0]                          o_port_2_mode,
  output logic                                o_port_2_start,
  input  wire                                 i_hw_wdata_port_2_start,
  input  wire                                 i_hw_we_port_2_start,
  output logic                                o_port_2_fault,
  input  wire                                 i_hw_wdata_port_2_fault,
  input  wire                                 i_hw_we_port_2_fault,
  output logic                                o_port_2_pending,
  input  wire                                 i_hw_wdata_port_2_pending,
  input  wire                                 i_hw_we_port_2_pending,
  output logic                                o_port_2_overflow,
  input  wire                                 i_hw_wdata_port_2_overflow,
  input  wire                                 i_hw_we_port_2_overflow,
  output logic                                o_port_2_done,
  input  wire                                 i_hw_wdata_port_2_done,
  input  wire                                 i_hw_we_port_2_done,

  // Register bank monitor
  input  wire  [PARA_MONITOR_COUNT-1:0][7:0]  i_monitor_sample_count,
  output logic [PARA_MONITOR_COUNT-1:0][3:0]  o_monitor_threshold,
  output logic [PARA_MONITOR_COUNT-1:0]       o_monitor_capture,
  input  wire  [PARA_MONITOR_COUNT-1:0]       i_hw_wdata_monitor_capture,
  input  wire  [PARA_MONITOR_COUNT-1:0]       i_hw_we_monitor_capture,
  output logic [PARA_MONITOR_COUNT-1:0]       o_monitor_error,
  input  wire  [PARA_MONITOR_COUNT-1:0]       i_hw_wdata_monitor_error,
  input  wire  [PARA_MONITOR_COUNT-1:0]       i_hw_we_monitor_error,
  output logic [PARA_MONITOR_COUNT-1:0]       o_monitor_pending,
  input  wire  [PARA_MONITOR_COUNT-1:0]       i_hw_wdata_monitor_pending,
  input  wire  [PARA_MONITOR_COUNT-1:0]       i_hw_we_monitor_pending,
  output logic [PARA_MONITOR_COUNT-1:0]       o_monitor_overflow,
  input  wire  [PARA_MONITOR_COUNT-1:0]       i_hw_wdata_monitor_overflow,
  input  wire  [PARA_MONITOR_COUNT-1:0]       i_hw_we_monitor_overflow,
  output logic [PARA_MONITOR_COUNT-1:0]       o_monitor_match,
  input  wire  [PARA_MONITOR_COUNT-1:0]       i_hw_wdata_monitor_match,
  input  wire  [PARA_MONITOR_COUNT-1:0]       i_hw_we_monitor_match,
  output logic [PARA_MONITOR_COUNT-1:0][14:0] o_monitor_key_fragment,
  input  wire  [PARA_MONITOR_COUNT-1:0]       i_hw_clear_monitor_key_fragment,

  // Register key
  output logic [31:0]                         o_key_data,
  input  wire                                 i_hw_clear_key_data
);

  // Internal signal declarations
  logic w_apb_setup;
  logic w_apb_prot_ok;
  logic w_apb_slverr;
  logic w_apb_complete;
  logic w_apb_wr;
  logic w_apb_rd;
  logic [LPARA_ADDR_W-1:0] reg_addr;
  logic [LPARA_DATA_W-1:0] reg_wdata;
  logic [LPARA_STRB_W-1:0] reg_wstrb;
  logic [LPARA_DATA_W-1:0] reg_wmask;
  logic reg_slverr;
  logic w_rd_en;
  logic w_wr_en;
  logic w_rd_ack_fall;
  logic [LPARA_DATA_W-1:0] w_rdata_nxt;
  logic [LPARA_DATA_W-1:0] reg_rdata;
  logic w_clk_reg;
  logic w_rst_n_reg;
  logic w_we_engine;
  logic w_rd_engine;
  logic [3:0] reg_engine_mode;
  logic [3:0] w_engine_mode_nxt;
  logic reg_engine_start;
  logic w_engine_start_nxt;
  logic reg_engine_fault;
  logic w_engine_fault_nxt;
  logic reg_engine_pending;
  logic w_engine_pending_nxt;
  logic reg_engine_overflow;
  logic w_engine_overflow_nxt;
  logic reg_engine_done;
  logic w_engine_done_nxt;
  logic [LPARA_DATA_W-1:0] w_engine_value;
  logic w_we_port_0;
  logic w_rd_port_0;
  logic [3:0] reg_port_0_mode;
  logic [3:0] w_port_0_mode_nxt;
  logic reg_port_0_start;
  logic w_port_0_start_nxt;
  logic reg_port_0_fault;
  logic w_port_0_fault_nxt;
  logic reg_port_0_pending;
  logic w_port_0_pending_nxt;
  logic reg_port_0_overflow;
  logic w_port_0_overflow_nxt;
  logic reg_port_0_done;
  logic w_port_0_done_nxt;
  logic [LPARA_DATA_W-1:0] w_port_0_value;
  logic w_we_port_1;
  logic w_rd_port_1;
  logic [3:0] reg_port_1_mode;
  logic [3:0] w_port_1_mode_nxt;
  logic reg_port_1_start;
  logic w_port_1_start_nxt;
  logic reg_port_1_fault;
  logic w_port_1_fault_nxt;
  logic reg_port_1_pending;
  logic w_port_1_pending_nxt;
  logic reg_port_1_overflow;
  logic w_port_1_overflow_nxt;
  logic reg_port_1_done;
  logic w_port_1_done_nxt;
  logic [LPARA_DATA_W-1:0] w_port_1_value;
  logic w_we_port_2;
  logic w_rd_port_2;
  logic [3:0] reg_port_2_mode;
  logic [3:0] w_port_2_mode_nxt;
  logic reg_port_2_start;
  logic w_port_2_start_nxt;
  logic reg_port_2_fault;
  logic w_port_2_fault_nxt;
  logic reg_port_2_pending;
  logic w_port_2_pending_nxt;
  logic reg_port_2_overflow;
  logic w_port_2_overflow_nxt;
  logic reg_port_2_done;
  logic w_port_2_done_nxt;
  logic [LPARA_DATA_W-1:0] w_port_2_value;
  logic [PARA_MONITOR_COUNT-1:0][3:0] reg_monitor_threshold;
  logic [PARA_MONITOR_COUNT-1:0][3:0] w_monitor_threshold_nxt;
  logic [PARA_MONITOR_COUNT-1:0] reg_monitor_capture;
  logic [PARA_MONITOR_COUNT-1:0] w_monitor_capture_nxt;
  logic [PARA_MONITOR_COUNT-1:0] reg_monitor_error;
  logic [PARA_MONITOR_COUNT-1:0] w_monitor_error_nxt;
  logic [PARA_MONITOR_COUNT-1:0] reg_monitor_pending;
  logic [PARA_MONITOR_COUNT-1:0] w_monitor_pending_nxt;
  logic [PARA_MONITOR_COUNT-1:0] reg_monitor_overflow;
  logic [PARA_MONITOR_COUNT-1:0] w_monitor_overflow_nxt;
  logic [PARA_MONITOR_COUNT-1:0] reg_monitor_match;
  logic [PARA_MONITOR_COUNT-1:0] w_monitor_match_nxt;
  logic [PARA_MONITOR_COUNT-1:0][14:0] reg_monitor_key_fragment;
  logic [PARA_MONITOR_COUNT-1:0][14:0] w_monitor_key_fragment_nxt;
  logic [PARA_MONITOR_COUNT-1:0] w_we_monitor;
  logic [PARA_MONITOR_COUNT-1:0] w_rd_monitor;
  logic [PARA_MONITOR_COUNT-1:0][LPARA_DATA_W-1:0] w_monitor_value;
  logic w_we_key;
  logic [31:0] reg_key_data;
  logic [31:0] w_key_data_nxt;
  logic [LPARA_DATA_W-1:0] w_key_value;

  // The parameter selects the register clock/reset for the chosen bus front end.
  assign w_clk_reg = (PARA_ASYNCHRONOUS == 32'd1) ? i_clk_reg : i_clk_apb;
  assign w_rst_n_reg = (PARA_ASYNCHRONOUS == 32'd1) ? i_rst_n_reg : i_rst_n_apb;


  // APB decode: the SETUP phase is PSEL high and PENABLE low and lasts one cycle per transfer.
  // A transfer is in error when the protection, the word alignment or the byte strobes fail
  // while i_slverr_en is 1.
  assign w_apb_setup    = i_apb_psel & ~i_apb_penable;
  assign w_apb_prot_ok  = i_protect_en ? ~i_apb_pprot[1] : 1'b1;
  assign w_apb_slverr   = i_slverr_en ? (~w_apb_prot_ok
                                         | (|i_apb_paddr[1:0])
                                         | (~&i_apb_pstrb[LPARA_STRB_W-1:0] & i_apb_pwrite)) : 1'b0;

  // Transfer without error, split into a write and a read.
  assign w_apb_complete = w_apb_setup & ~w_apb_slverr;
  assign w_apb_wr       = i_apb_pwrite & w_apb_complete;
  assign w_apb_rd       = ~i_apb_pwrite & w_apb_complete;

  // Address capture: holds the address of the last transfer without error.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_addr
    if (!i_rst_n_apb)
      reg_addr <= '0;
    else if (w_apb_complete)
      reg_addr <= i_apb_paddr;
  end

  // Write data capture: holds the data of the last write without error.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_wdata
    if (!i_rst_n_apb)
      reg_wdata <= '0;
    else if (w_apb_wr)
      reg_wdata <= i_apb_pwdata;
  end

  // Write byte strobes are captured with the write payload and expanded to field-bit masks.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_wstrb
    if (!i_rst_n_apb)
      reg_wstrb <= '0;
    else if (w_apb_wr)
      reg_wstrb <= i_apb_pstrb[LPARA_STRB_W-1:0];
  end
  generate
    for (genvar gen_lane = 0; gen_lane < LPARA_STRB_W; gen_lane++) begin : gen_apb_wmask
      assign reg_wmask[(gen_lane * 8) +: 8] = {8{reg_wstrb[gen_lane]}};
    end
  endgenerate

  // Error response flop: loaded in every SETUP phase while i_slverr_en is 1, and held otherwise.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_slverr
    if (!i_rst_n_apb)
      reg_slverr <= 1'b0;
    else if (w_apb_setup & i_slverr_en)
      reg_slverr <= w_apb_slverr;
  end

  // PSLVERR output follows the error response flop.
  assign o_apb_pslverr = reg_slverr;

  // Per-register write/read address enables.
  assign w_we_engine = w_wr_en & (reg_addr == LPARA_ENGINE_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_port_0 = w_wr_en & (reg_addr == LPARA_PORT_0_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_port_1 = w_wr_en & (reg_addr == LPARA_PORT_1_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_port_2 = w_wr_en & (reg_addr == LPARA_PORT_2_OFFSET[LPARA_ADDR_W-1:0]);
  // Decode a software write independently for every generated register index.
  generate
  for (genvar gen_idx = 0; (gen_idx < PARA_MONITOR_COUNT) && (gen_idx < LPARA_MONITOR_MAX_COUNT); gen_idx++) begin : gen_monitor_we_decode
    assign w_we_monitor[gen_idx] = w_wr_en & (32'(reg_addr) == (LPARA_MONITOR_BASE_OFFSET + (gen_idx * LPARA_MONITOR_OFFSET_STRIDE)));
  end
  endgenerate
  assign w_we_key = w_wr_en & (reg_addr == LPARA_KEY_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_rd_engine = w_rd_en & (reg_addr == LPARA_ENGINE_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_rd_port_0 = w_rd_en & (reg_addr == LPARA_PORT_0_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_rd_port_1 = w_rd_en & (reg_addr == LPARA_PORT_1_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_rd_port_2 = w_rd_en & (reg_addr == LPARA_PORT_2_OFFSET[LPARA_ADDR_W-1:0]);
  // Decode a software read independently for every generated register index.
  generate
  for (genvar gen_idx = 0; (gen_idx < PARA_MONITOR_COUNT) && (gen_idx < LPARA_MONITOR_MAX_COUNT); gen_idx++) begin : gen_monitor_rd_decode
    assign w_rd_monitor[gen_idx] = w_rd_en & (32'(reg_addr) == (LPARA_MONITOR_BASE_OFFSET + (gen_idx * LPARA_MONITOR_OFFSET_STRIDE)));
  end
  endgenerate

  // Register transaction events are qualified by the captured APB transfer.
  // Read events include aligned unmapped reads, which return zero. Unaligned reads
  // are suppressed even when the APB error response is disabled.
  assign o_reg_rd_en   = w_rd_en & (reg_addr[1:0] == 2'b00);
  assign o_reg_rd_addr = o_reg_rd_en ? reg_addr : '0;

  // Write events are asserted only for a mapped register with at least one
  // software-writable field; rejected and read-only writes do not assert this event.
  assign o_reg_wr_en   =
    (|w_we_engine)
    | (|w_we_port_0)
    | (|w_we_port_1)
    | (|w_we_port_2)
    | (|w_we_monitor)
    | (|w_we_key);
  assign o_reg_wr_addr = o_reg_wr_en ? reg_addr : '0;

  // Elaboration selects one clock architecture for this single RTL module.
  generate
    if (PARA_ASYNCHRONOUS == 32'd1) begin : g_async_csr

      // Async-only request, acknowledge, and synchronizer state.
      logic w_rd_ack;
      logic w_rd_ack_bus;
      logic reg_rd_req;
      logic w_rd_req_nxt;
      logic reg_rd_ack_bus_dly;
      logic w_wr_ack;
      logic w_wr_ack_bus;
      logic reg_wr_req;
      logic w_wr_req_nxt;
      logic w_wr_ack_fall;
      logic reg_wr_ack_bus_dly;
      logic w_rd_req_reg;
      logic reg_rd_req_reg_dly;
      logic w_wr_req_reg;
      logic reg_wr_req_reg_dly;
      logic w_pready_nxt;
      logic reg_pready;

      // Read request and acknowledge toggles cross between the APB and register clocks.
      m_csr_sync #(
        .PARA_LEVELS (LPARA_SYNC_STAGES)
      ) u_rd_ack_sync (
        .i_clk_dst   (i_clk_apb),
        .i_rst_n_dst (i_rst_n_apb),
        .i_d         (w_rd_ack),
        .o_q         (w_rd_ack_bus)
      );

      // APB read request is set on a read and cleared by its synchronized acknowledge.
      assign w_rd_req_nxt  = w_rd_ack_bus ? 1'b0 : (w_apb_rd ? 1'b1 : reg_rd_req);
      assign w_rd_ack_fall = reg_rd_ack_bus_dly & ~w_rd_ack_bus;
      always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_rd_req
        if (!i_rst_n_apb) begin
          reg_rd_req         <= 1'b0;
          reg_rd_ack_bus_dly <= 1'b0;
        end else begin
          reg_rd_req         <= w_rd_req_nxt;
          reg_rd_ack_bus_dly <= w_rd_ack_bus;
        end
      end

      // APB write request uses an independent request/acknowledge toggle.
      m_csr_sync #(
        .PARA_LEVELS (LPARA_SYNC_STAGES)
      ) u_wr_ack_sync (
        .i_clk_dst   (i_clk_apb),
        .i_rst_n_dst (i_rst_n_apb),
        .i_d         (w_wr_ack),
        .o_q         (w_wr_ack_bus)
      );
      assign w_wr_req_nxt  = w_wr_ack_bus ? 1'b0 : (w_apb_wr ? 1'b1 : reg_wr_req);
      assign w_wr_ack_fall = reg_wr_ack_bus_dly & ~w_wr_ack_bus;
      always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_wr_req
        if (!i_rst_n_apb) begin
          reg_wr_req         <= 1'b0;
          reg_wr_ack_bus_dly <= 1'b0;
        end else begin
          reg_wr_req         <= w_wr_req_nxt;
          reg_wr_ack_bus_dly <= w_wr_ack_bus;
        end
      end

      // Read request is synchronized into the register clock domain.
      m_csr_sync #(
        .PARA_LEVELS (LPARA_SYNC_STAGES)
      ) u_rd_req_sync (
        .i_clk_dst   (i_clk_reg),
        .i_rst_n_dst (i_rst_n_reg),
        .i_d         (reg_rd_req),
        .o_q         (w_rd_req_reg)
      );
      always_ff @(posedge i_clk_reg, negedge i_rst_n_reg) begin : p_ff_rd_req_reg
        if (!i_rst_n_reg)
          reg_rd_req_reg_dly <= 1'b0;
        else
          reg_rd_req_reg_dly <= w_rd_req_reg;
      end
      assign w_rd_en  = ~reg_rd_req_reg_dly & w_rd_req_reg;
      assign w_rd_ack = reg_rd_req_reg_dly;

      // Write request is synchronized into the register clock domain.
      m_csr_sync #(
        .PARA_LEVELS (LPARA_SYNC_STAGES)
      ) u_wr_req_sync (
        .i_clk_dst   (i_clk_reg),
        .i_rst_n_dst (i_rst_n_reg),
        .i_d         (reg_wr_req),
        .o_q         (w_wr_req_reg)
      );
      always_ff @(posedge i_clk_reg, negedge i_rst_n_reg) begin : p_ff_wr_req_reg
        if (!i_rst_n_reg)
          reg_wr_req_reg_dly <= 1'b0;
        else
