      default: begin
        w_rdata_nxt = '0;
      if ((PARA_MONITOR_COUNT >= 32'd1) && (PARA_MONITOR_COUNT <= LPARA_MONITOR_MAX_COUNT)) begin
        case (32'(reg_addr))
          (LPARA_MONITOR_BASE_OFFSET + (32'd0 * LPARA_MONITOR_OFFSET_STRIDE)): begin
            if (PARA_MONITOR_COUNT > 32'd0)
              w_rdata_nxt = w_monitor_value[0];
          end
          (LPARA_MONITOR_BASE_OFFSET + (32'd1 * LPARA_MONITOR_OFFSET_STRIDE)): begin
            if (PARA_MONITOR_COUNT > 32'd1)
              w_rdata_nxt = w_monitor_value[1];
          end
          (LPARA_MONITOR_BASE_OFFSET + (32'd2 * LPARA_MONITOR_OFFSET_STRIDE)): begin
            if (PARA_MONITOR_COUNT > 32'd2)
              w_rdata_nxt = w_monitor_value[2];
          end
          (LPARA_MONITOR_BASE_OFFSET + (32'd3 * LPARA_MONITOR_OFFSET_STRIDE)): begin
            if (PARA_MONITOR_COUNT > 32'd3)
              w_rdata_nxt = w_monitor_value[3];
          end
          default: w_rdata_nxt = '0;
        endcase
      end
      end
    endcase
  end

  // Read response storage follows the selected clock architecture.
  generate
    if (PARA_ASYNCHRONOUS == 32'd1) begin : g_async_rdata
      logic [LPARA_DATA_W-1:0] reg_rdata_bus;

      // Snapshot read data in the register clock domain.
      always_ff @(posedge i_clk_reg, negedge i_rst_n_reg) begin : p_ff_rdata
        if (!i_rst_n_reg)
          reg_rdata <= '0;
        else if (w_rd_en)
          reg_rdata <= w_rdata_nxt;
      end

      // The synchronized acknowledge qualifies the stable bundled read data.
      always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_rdata_bus
        if (!i_rst_n_apb)
          reg_rdata_bus <= '0;
        else if (w_rd_ack_fall)
          reg_rdata_bus <= reg_rdata;
      end
      assign o_apb_prdata = reg_rdata_bus;
    end else begin : g_sync_rdata
      // Synchronous read data is captured in the APB/register clock domain.
      always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_rdata
        if (!i_rst_n_apb)
          reg_rdata <= '0;
        else if (w_rd_en)
          reg_rdata <= w_rdata_nxt;
      end
      assign o_apb_prdata = reg_rdata;
    end
  endgenerate

endmodule
